import{_ as t,o as e,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Calendar Task View","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-5-calendar-task-view/spec.md","filePath":"feature/content-task-workflow/3-6-5-calendar-task-view/spec.md"}'),r={name:"feature/content-task-workflow/3-6-5-calendar-task-view/spec.md"};function i(s,a,c,l,d,h){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="uc-—-calendar-task-view" tabindex="-1">UC — Calendar Task View <a class="header-anchor" href="#uc-—-calendar-task-view" aria-label="Permalink to &quot;UC — Calendar Task View&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.6.5</td></tr><tr><td>Feature</td><td>Calendar Task View</td></tr><tr><td>Domain</td><td>Content &amp; Workflow (FR 3.6)</td></tr><tr><td>Role</td><td>CREATOR, CLIENT, MANAGER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Hiển thị Task dạng lịch kiểu Google Calendar, kéo thả được để đổi ngày.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một Creator, Client, hoặc Manager, tôi muốn xem Task theo dạng lịch, để nắm được phân bổ công việc theo ngày/tuần/tháng.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Hiển thị Task theo <code>dueDate</code> trên lưới calendar (tháng/tuần/ngày).</li><li>Kéo thả 1 Task sang ngày khác → cập nhật <code>dueDate</code> ngay (chỉ Manager/Creator được kéo, Client chỉ xem).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/workspaces/:id/tasks?view=calendar</code>.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/workspaces/{id}/tasks?view=calendar&amp;month=2026-09</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;id&quot;, &quot;title&quot;, &quot;dueDate&quot;, &quot;status&quot; }] }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PATCH /api/v1/workspaces/{id}/tasks/{taskId}/reschedule</span></span>
<span class="line"><span>{ &quot;dueDate&quot;: &quot;ISO date&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { ...task... } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>Client cố kéo thả đổi ngày → 403 <code>FORBIDDEN</code> (chỉ Manager/Creator được sửa dueDate).</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Kéo Task sang ngày đã qua (trong quá khứ) → cảnh báo xác nhận trước khi lưu, không tự động chặn cứng.</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Calendar hiển thị đúng, kéo thả cập nhật deadline hoạt động cho Manager/Creator.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/05-content-task-workflow.html">05-content-task-workflow.md</a></p>`,22)])])}const k=t(r,[["render",i]]);export{p as __pageData,k as default};
